// Generated by duckwright from history.json. Review before committing:
// recorded code contains everything the agent typed, passwords included.
import { test, expect } from '@playwright/test';
import { createHmac } from 'node:crypto';

function totp(secret = process.env.DUCKWRIGHT_TOTP_SECRET, name = 'DUCKWRIGHT_TOTP_SECRET') {
  if (!secret) throw new Error(`set ${name} to run this test`);
  if (/^otpauth:/i.test(secret)) secret = new URL(secret).searchParams.get('secret') || '';
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const bytes = [];
  let bits = 0;
  let acc = 0;
  for (const ch of secret.replace(/[\s=-]/g, '').toUpperCase()) {
    acc = (acc << 5) | alphabet.indexOf(ch);
    bits += 5;
    if (bits >= 8) {
      bytes.push((acc >>> (bits - 8)) & 255);
      bits -= 8;
      acc &= (1 << bits) - 1;
    }
  }
  const counter = Buffer.alloc(8);
  counter.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
  const mac = createHmac('sha1', Buffer.from(bytes)).update(counter).digest();
  const offset = mac[mac.length - 1] & 15;
  const value = ((mac[offset] & 127) << 24) | (mac[offset + 1] << 16) | (mac[offset + 2] << 8) | mac[offset + 3];
  return String(value % 1000000).padStart(6, '0');
}

test("log in as admin", async ({ page }) => {
  await page.goto('https://example.com/login');
  await page.getByRole('textbox', { name: 'Email' }).fill('admin@example.com');
  await page.getByRole('textbox', { name: 'Password' }).fill(process.env.DW_DEV_ADMIN_C_PASSWORD);
  await page.getByLabel('Code').fill(totp(process.env.DW_DEV_ADMIN_C_TOTP, 'DW_DEV_ADMIN_C_TOTP')); // 2FA
  await expect(page).toHaveURL('https://example.com/home');
});
